// reprSpelling is v's string body as Python's repr() writes it (the form
// ansible-core prints when a dict or list holding v is interpolated into a
// larger string, or passed through the `string` filter). repr picks single
// quotes unless v contains ' and no ", so only the both-quotes case escapes
// a quote: ' becomes \'. Backslash, \n, \r, \t and other non-printables are
// escaped as Python does (\xNN, \uNNNN, \UNNNNNNNN).
func reprSpelling(v string) string {
	sq := strings.Contains(v, "'") && strings.Contains(v, `"`)
	var sb strings.Builder
	for _, r := range v {
		switch {
		case r == '\\':
			sb.WriteString(`\\`)
		case r == '\'' && sq:
			sb.WriteString(`\'`)
		case r == '\n':
			sb.WriteString(`\n`)
		case r == '\r':
			sb.WriteString(`\r`)
		case r == '\t':
			sb.WriteString(`\t`)
		case r < 0x20 || r == 0x7f:
			fmt.Fprintf(&sb, `\x%02x`, r)
		default:
			sb.WriteRune(r) // match str.isprintable() for non-ASCII in a full fix
		}
	}
	return sb.String()
}

